// justify-content: normal, stretch, start, end, flex-start, flex-end, center and the three space distributions (else std::invalid_argument).
template <typename Declaring>
struct GridPanelJustifyContentCapability {
    PropertyCell<LayoutAlignment, GridPanelJustifyContentCapability<Declaring>> justify_content{LayoutAlignment::normal};

    static void assign(GridPanelJustifyContentCapability& capability, LayoutAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.justify_content), incoming);
        if (!capability.justify_content.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.justify_content));
    }
};

